(function() {
        if (!document.getElementById('pdf-container')) return;
        var PDF_DATA = atob("");
        var uint8 = new Uint8Array(PDF_DATA.length);
        for (var i = 0; i < PDF_DATA.length; i++) uint8[i] = PDF_DATA.charCodeAt(i);

        var script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
        script.onload = function() {
          pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
          pdfjsLib.getDocument({data: uint8}).promise.then(function(pdf) {
            document.getElementById('pdf-loading').style.display = 'none';
            var scale = 2.0;
            var container = document.getElementById('pdf-container');
            var containerWidth = container.offsetWidth - 32;

            function renderPage(pageNum) {
              return pdf.getPage(pageNum).then(function(page) {
                var viewport = page.getViewport({scale: scale});
                var canvas = document.getElementById('pdf-canvas-' + pageNum);
                if (!canvas) {
                  canvas = document.createElement('canvas');
                  canvas.id = 'pdf-canvas-' + pageNum;
                  canvas.style.cssText = 'width:100%;border-radius:4px;margin-bottom:12px;box-shadow:0 1px 8px rgba(0,0,0,.08)';
                  container.appendChild(canvas);
                }
                canvas.style.display = 'block';
                var ctx = canvas.getContext('2d');
                canvas.height = viewport.height;
                canvas.width = viewport.width;
                canvas.style.width = containerWidth + 'px';
                canvas.style.height = (containerWidth * viewport.height / viewport.width) + 'px';
                return page.render({canvasContext: ctx, viewport: viewport}).promise;
              });
            }

            var pages = [];
            for (var p = 1; p <= pdf.numPages; p++) pages.push(renderPage(p));
            Promise.all(pages);
            }).catch(function(e) {
            document.getElementById('pdf-loading').innerHTML = 'Could not render PDF. <a href="assets/pdf/Rohan_CV v6.pdf" download style="color:var(--navy)">Download instead ↓</a>';
          });
        };
        document.head.appendChild(script);
      })();

function toggleSticky(btn) {
  var details = btn.nextElementSibling;
  var isOpen = details.classList.contains('open');
  details.classList.toggle('open', !isOpen);
  btn.classList.toggle('open', !isOpen);
  btn.textContent = isOpen ? '+ Details' : '− Details';
}

function toggleCard(header) {
  var btn = header.querySelector('.proj-expand-btn');
  var details = header.parentElement.querySelector('.proj-details');
  var isOpen = details.classList.contains('open');
  details.classList.toggle('open', !isOpen);
  btn.classList.toggle('open', !isOpen);
}

function getCurrentPage() {
  var filename = window.location.pathname.split('/').pop();
  if (filename === 'about.html') return 'about';
  if (filename === 'projects.html') return 'projects';
  if (filename === 'blog.html') return 'blog';
  if (filename === 'contact.html') return 'contact';
  if (filename === 'resume.html') return 'resume';
  return 'home';
}

function setActiveNav() {
  var current = getCurrentPage();
  document.querySelectorAll('.nav-tab').forEach(function(tab) {
    tab.classList.toggle('active', tab.dataset.page === current);
  });
}

setActiveNav();
